import{_ as I,o as a,c as t,a0 as l}from"./chunks/framework.DQOulFGV.js";const s="data:image/svg+xml;base64,",e="data:image/svg+xml;base64,",o=JSON.parse('{"title":"第5章 过期删除","description":"","frontmatter":{},"headers":[],"relativePath":"redis/02-standalone-core/chapter-05-expiration.md","filePath":"redis/02-standalone-core/chapter-05-expiration.md"}'),d={name:"redis/02-standalone-core/chapter-05-expiration.md"};function n(g,i,p,h,m,c){return a(),t("div",null,[...i[0]||(i[0]=[l(`<h1 id="第5章-过期删除" tabindex="-1">第5章 过期删除 <a class="header-anchor" href="#第5章-过期删除" aria-label="Permalink to &quot;第5章 过期删除&quot;">​</a></h1><blockquote><p>缓存数据往往有生命周期，过期后需要及时删除以释放内存。Redis 用「惰性删除 + 定期删除」两条策略配合，在内存占用与 CPU 开销之间取得平衡。本章讲解过期键的存储与删除机制。</p></blockquote><hr><h2 id="_5-1-过期键存储" tabindex="-1">5.1 过期键存储 <a class="header-anchor" href="#_5-1-过期键存储" aria-label="Permalink to &quot;5.1 过期键存储&quot;">​</a></h2><p>Redis 为设置了 TTL 的键维护一个独立的过期字典，专门记录键的过期时间。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>expires 字典（独立的哈希表）</span></span>
<span class="line"><span>  &quot;session:abc&quot;  →  1712500000000（毫秒时间戳）</span></span>
<span class="line"><span>  &quot;cache:order&quot;  →  1712500360000</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><p>设置过期时间的命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXPIRE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 300 秒后过期</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PEXPIRE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 300000 毫秒后过期</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> value</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EX</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 设置时直接指定过期时间</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TTL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 查看剩余时间（秒）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PERSIST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 移除过期时间，永久保留</span></span></code></pre></div><p>关键设计：过期时间单独存放在 <code>expires</code> 字典里，与主数据字典分离。这样查找某个键是否过期，只需查 <code>expires</code> 字典，O(1)。</p><hr><h2 id="_5-2-惰性删除" tabindex="-1">5.2 惰性删除 <a class="header-anchor" href="#_5-2-惰性删除" aria-label="Permalink to &quot;5.2 惰性删除&quot;">​</a></h2><p>惰性删除指「访问时才发现过期、才删除」——键过期后不主动清理，等客户端访问这个键时检查并删除。</p><p><img src="`+s+`" alt="惰性删除流程"></p><p>特点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">优点</td><td style="text-align:left;">只在访问时检查，不额外消耗 CPU</td></tr><tr><td style="text-align:left;">缺点</td><td style="text-align:left;">过期键长期不被访问就一直占内存</td></tr><tr><td style="text-align:left;">适用</td><td style="text-align:left;">作为补充策略，处理「访问到的过期键」</td></tr></tbody></table><hr><h2 id="_5-3-定期删除" tabindex="-1">5.3 定期删除 <a class="header-anchor" href="#_5-3-定期删除" aria-label="Permalink to &quot;5.3 定期删除&quot;">​</a></h2><p>定期删除指「定时主动扫描并删除一批过期键」——每隔一段时间随机抽取一些键，删除其中已过期的。</p><h3 id="执行机制" tabindex="-1">执行机制 <a class="header-anchor" href="#执行机制" aria-label="Permalink to &quot;执行机制&quot;">​</a></h3><p>Redis 默认每 100 毫秒执行一次定期删除：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每次执行：</span></span>
<span class="line"><span>1. 从 expires 字典随机抽取 20 个键</span></span>
<span class="line"><span>2. 删除其中已过期的键</span></span>
<span class="line"><span>3. 若已过期键占比 &gt; 25%，重复步骤 1~2（继续这一轮）</span></span>
<span class="line"><span>4. 否则本轮结束，等待下一次</span></span></code></pre></div><p>关键参数：</p><table tabindex="0"><thead><tr><th style="text-align:left;">参数</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;">20 个</td><td style="text-align:left;">每次随机抽取的键数量</td></tr><tr><td style="text-align:left;">25%</td><td style="text-align:left;">过期占比阈值，超过则继续扫描</td></tr><tr><td style="text-align:left;">100ms</td><td style="text-align:left;">执行周期</td></tr></tbody></table><p>特点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">优点</td><td style="text-align:left;">主动清理，避免过期键长期堆积</td></tr><tr><td style="text-align:left;">缺点</td><td style="text-align:left;">随机抽取，可能漏掉部分过期键</td></tr><tr><td style="text-align:left;">时间上限</td><td style="text-align:left;">单次执行有 CPU 时间上限，防止阻塞主线程</td></tr></tbody></table><hr><h2 id="_5-4-两种策略的配合" tabindex="-1">5.4 两种策略的配合 <a class="header-anchor" href="#_5-4-两种策略的配合" aria-label="Permalink to &quot;5.4 两种策略的配合&quot;">​</a></h2><p>惰性删除与定期删除是互补的：</p><p><img src="`+e+'" alt="惰性删除与定期删除配合"></p><ul><li><strong>定期删除</strong>负责「主动」清理大部分过期键，控制内存</li><li><strong>惰性删除</strong>负责「被动」清理被访问到的过期键，保证返回正确</li></ul><p>两者结合，既避免「过期键长期占内存」（纯惰性的缺点），又避免「扫描开销过大阻塞服务」（纯定期的缺点）。</p><blockquote><p>即使有这两种策略，仍可能有少量过期键暂时留在内存里。当内存紧张时，就会触发内存淘汰策略（见第 6 章）来兜底。</p></blockquote>',32)])])}const r=I(d,[["render",n]]);export{o as __pageData,r as default};
